mapper.select:
SELECT session_id, max_tickets_per_member, version, seat_rows, seats_per_row
FROM interviewworks_ticket.session_sales_settings
WHERE session_id = #{sessionId}

SELECT coalesce(sum(quantity), 0)
FROM interviewworks_ticket.ticket
WHERE session_id = #{sessionId}
  AND email = #{email}
  AND (status = 'PAID' OR (status = 'PENDING_PAYMENT' AND expires_at > CURRENT_TIMESTAMP))

mapper.update:
UPDATE interviewworks_ticket.session_seat
SET zone_id = NULL
WHERE session_id = #{sessionId}
